import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "बार बार दस्त, पेट में दर्द, या मल में म्यूकस? यह आई बी एस है, या आंतों की सूजन वाली बीमारी, आई बी डी? इसे समझने में मदद करता है, मल का एक आसान टेस्ट, फीकल कैलप्रोटेक्टिन. आखिर तक देखिए.",
 "कैलप्रोटेक्टिन एक प्रोटीन है, जो न्यूट्रोफिल नाम की सफेद रक्त कोशिकाओं में होता है. जब आंतों में सूजन होती है, तो ये कोशिकाएं वहां इकट्ठा होती हैं, और कैलप्रोटेक्टिन मल में आ जाता है. जितनी ज़्यादा सूजन, उतना ज़्यादा कैलप्रोटेक्टिन.",
 "आई बी एस में आंतें संवेदनशील होती हैं, पर सूजन नहीं होती, इसलिए कैलप्रोटेक्टिन आमतौर पर सामान्य रहता है. क्रोन्स डिज़ीज़ और अल्सरेटिव कोलाइटिस जैसी आई बी डी में, असली सूजन होती है, और यह बढ़ जाता है. इससे डॉक्टर तय कर पाते हैं, कि किसे कोलोनोस्कोपी की ज़रूरत है.",
 "डॉक्टर यह जांच कब कहते हैं? लंबे समय से दस्त, पेट दर्द, या म्यूकस हो, और आई बी एस और आई बी डी में फर्क करना हो. और जिन्हें आई बी डी है, उनमें बीमारी की सक्रियता, और इलाज का असर देखने के लिए.",
 "रिपोर्ट कैसे समझें? आमतौर पर पचास माइक्रोग्राम प्रति ग्राम से कम, सामान्य माना जाता है. बीच की रेंज में, कुछ हफ्तों बाद दोबारा जांच कही जा सकती है. और ज़्यादा वैल्यू, आंतों में सूजन का इशारा है. रेंज, हर लैब में थोड़ी अलग हो सकती है.",
 "ध्यान दें, यह सिर्फ आई बी डी का टेस्ट नहीं है. पेट का इन्फेक्शन, दर्द की दवाएं जैसे एन सेड्स, एसिडिटी की दवाएं, सीलिएक बीमारी, और आंत का कैंसर भी इसे बढ़ा सकते हैं. दो साल से छोटे बच्चों में, यह सामान्य रूप से थोड़ा ज़्यादा हो सकता है.",
 "सैंपल कैसे दें? साफ डिब्बी में, थोड़ा सा मल लें, जितना लैब बताए. इसमें पेशाब या पानी न मिले. डिब्बी के बाहर गंदगी न लगे. और सैंपल जल्द से जल्द, लैब के बताए समय के अंदर पहुंचाएं.",
 "ज़रूरी बात. मल में खून, वज़न घटना, खून की कमी, या ज़्यादा उम्र में पहली बार पेट की आदत बदलना, ऐसे लक्षणों में, इस टेस्ट का इंतज़ार न करें, तुरंत डॉक्टर से मिलें. दर्द या एसिडिटी की दवाएं लेते हों, तो डॉक्टर को बताएं, खुद से बंद न करें.",
 close_voice("क्या आपने कभी फीकल कैलप्रोटेक्टिन टेस्ट करवाया है?"),
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/fcpr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/fcp_{i}.wav"],check=True); f=f"/tmp/fcp_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/fcp_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
